var t=[{title:`Způsoby měření`,text:`Nový rekord v zátěži je snadné poznat, ale 10 kontrolovaných opakování s váhou, která dřív umožňovala sedm, je také pokrok. U cviků s vlastní vahou se můžete zlepšit snížením sklonu kliku, přidáním rozsahu pohybu nebo přechodem z asistovaných opakování na neasistovaná.`},{title:`Odhadovaná a testovaná maxima`,text:`Vaše jednoopakovací maximum (1RM) je nejtěžší zátěž, kterou zvednete jednou s přijatelnou technikou. Vzorce ho mohou odhadnout z lehčích sérií, ale odhady jsou méně spolehlivé u různých cviků, při vyšších počtech opakování a mezi jednotlivými cvičenci. Začátečníci testy maxima ke sledování pokroku nepotřebují.`},{title:`Porovnávejte stejné se stejným`,text:`Držte úchop, hloubku, tempo, vybavení a odpočinek při porovnávání tréninků zhruba stejné. Těžší částečný dřep se automaticky nerovná lehčímu dřepu v plném rozsahu. Víc kontroly, jistoty nebo vytrvalosti při stejné zátěži se také počítá jako zlepšení, s novým maximem či bez něj.`},{title:`Příklad`,text:`Přítah se zlepší z 3 × 8 na 3 × 12 se stejnou jednoručkou a podobnou technikou. Pak můžete zkusit malé zvýšení zátěže a znovu se propracovat rozsahem opakování.`},{title:`Použití v TrainUp`,text:`TrainUp nepředepisuje váhy: zátěž volíte vy. Váš plán dává pro každý cvik série a opakování a během tréninku zaznamenáváte opakování, která jste skutečně udělali.`}];var n=[{label:`Stanovisko ACSM z roku 2026`,url:`https://pubmed.ncbi.nlm.nih.gov/41843416/`},{label:`Praktické doporučení ACSM 2026`,url:`https://www.acsm.org/wp-content/uploads/2026/03/Resistance-Training-Position-Stand-infographic.pdf`}];var a={sections:t,sources:n};export{a as default,t as sections,n as sources};